/* Floor display, recoverable corrections, station alerts, and people's hours. */
function activeJobs(){return state.jobs.filter(j=>!j.deletedAt);}
function contribution(j){const before=percent({...j,end:j.start}),planned=earnedMinutes({...j,end:j.goal}),attainment=planned>0?Math.round(earnedMinutes(j)/planned*100)+'% of planned work':'No planned work';return `${before}% → ${percent(j)}% complete · +${percent(j)-before} percentage points this assignment · ${attainment}`;}
const hoursValue=m=>m==null?'':Math.round(m/60*100)/100;
// New assignments take their regular hours from what the named people have left today, until the field is typed in.
let autoPlan=false,peopleView='all';
// Splitting a person's day across units is the exception, so it sits behind one disclosure.
function jobTimeFields(j){autoPlan=!j.id;return `<details class="time-details split-day" ${j.id&&j.productiveMinutes<state.operations.requiredMinutes?'open':''}><summary>Split this person's day across units</summary><p class="form-hint">Regular hours fill in from what the named people have left of their ${fmtHours(state.operations.requiredMinutes/60)} h day. Lower them when someone moves to another unit partway through the day. Two names share one plan; they do not double it.</p><div class="form-grid"><label class="field">Regular hours on this unit<input name="allocationHours" type="number" min="0" max="24" step="any" required value="${hoursValue(j.productiveMinutes)}"></label><div class="field allocation-note" id="allocation-note" aria-live="polite"></div></div></details>`;}
function planContext(){const f=$('#job-form');return {operators:f.elements.operators.value,date:f.elements.date.value,excludeId:editingId,operations:state.operations,offUnit:state.offUnit};}
// Regular hours are capped at the standard day; anything more goes in Additional hours worked.
function openHours(){return Math.min(QuestTracking.availability(activeJobs(),planContext()).openMinutes,state.operations.requiredMinutes);}
function updateAllocationNote(){
 const f=$('#job-form');if(!f.elements.allocationHours)return;
 const a=QuestTracking.availability(activeJobs(),planContext());if(autoPlan&&a.people.length)f.elements.allocationHours.value=hoursValue(openHours());
 const planned=Number(f.elements.allocationHours.value)*60,over=a.people.length&&planned>a.openMinutes+1e-6;
 if(a.people.length&&(planned<state.operations.requiredMinutes||over))$('.split-day').open=true;
 $('#allocation-note').innerHTML=(a.people.map(p=>`<span><b>${esc(p.name)}</b> ${fmtHours(p.requiredMinutes/60)} h day · ${fmtHours(p.bookedMinutes/60)} h on other units or training · <b>${fmtHours(p.openMinutes/60)} h left</b></span>`).join('')||'<span>Add a name to see the hours each person has left today.</span>')+(over?'<span class="allocation-warning">More than the regular hours left today. Put the extra in Additional hours worked.</span>':'');
}
function nextUnit(id){const source=activeJobs().find(j=>j.id===id);if(!source||tv)return;if(!source.closed){notify('Finish this assignment before starting the next unit.');openJob(id);return;}const open=Math.min(QuestTracking.availability(activeJobs(),{operators:source.operators,date:source.date,operations:state.operations,offUnit:state.offUnit}).openMinutes,state.operations.requiredMinutes);openJob(null,null,{processId:source.processId,cell:source.cell,date:source.date,shift:source.shift,operators:source.operators,productiveMinutes:open,allocationExplicit:true});notify(`New unit · ${fmtHours(open/60)} h left today`);}
function timeValidation(j){if(!Number.isFinite(j.productiveMinutes)||j.productiveMinutes<0||j.productiveMinutes>1440)return 'Enter regular hours between 0 and 24.';return QuestTracking.validateHours(j);}
// One line for an assignment's time: hours worked, waiting, and what was left to build.
function observedTime(j){const h=QuestTracking.hours(j);return `${fmtHours(h.workedMinutes/60)} h worked${h.overtimeMinutes?` (incl. ${fmtHours(h.overtimeMinutes/60)} h additional)`:''} · ${h.waitMinutes?`${fmtHours(h.waitMinutes/60)} h waiting${j.delayReason?': '+esc(j.delayReason):''}`:'no waiting'} · ${fmtHours(h.buildMinutes/60)} h to build`;}
const signedHours=m=>m==null?'—':`${m>0?'+':m<0?'−':''}${fmtHours(Math.abs(m)/60)} h`;
const pct=r=>r==null?'—':`${Math.round(r*100)}%`;
// Person grade only once the shift is finished; process efficiency as soon as waiting is recorded.
function gradesText(j){const g=QuestTracking.grades(j,earnedMinutes(j));return `Person grade ${j.closed&&!j.training?pct(g.person):'—'} · Process ${pct(g.process)}`;}
// Whole-unit totals for unit history: time-study hours earned against the hours it took to build.
function unitSummary(rows){const u=QuestTracking.unitFlow(rows,earnedMinutes)[0];if(!u)return '';return `<div class="unit-summary"><div><span>Time study earned</span><strong>${fmtHours(u.standardMinutes/60)} h</strong><small>${u.assignments} assignment${u.assignments===1?'':'s'} · ${u.people.length} ${u.people.length===1?'person':'people'}</small></div><div><span>Hours to build</span><strong>${fmtHours(u.buildMinutes/60)} h</strong><small>${signedHours(u.overMinutes)} vs. time study</small></div><div><span>Process efficiency</span><strong>${pct(u.processEfficiency)}</strong><small>${fmtHours(u.waitMinutes/60)} h waiting${u.reasons.length?': '+u.reasons.map(([r,m])=>`${esc(r)} ${fmtHours(m/60)} h`).join(' · '):''}</small></div><div><span>Below shift goal</span><strong>${u.belowGoal}</strong><small>Finished, non-training shifts</small></div></div>`;}
function hoursMeter(l){const scale=Math.max(l.requiredMinutes,l.bookedMinutes,1),w=m=>`${Math.min(100,m/scale*100)}%`,unbooked=Math.max(0,l.requiredMinutes-l.bookedMinutes);return `<div class="hours-meter" role="img" aria-label="${fmtHours(l.buildMinutes/60)} h building, ${fmtHours(l.waitMinutes/60)} h waiting, ${fmtHours(l.offUnitMinutes/60)} h training or off-unit, ${fmtHours(unbooked/60)} h not booked, of a ${fmtHours(l.requiredMinutes/60)} h day"><span class="work" style="width:${w(l.buildMinutes)}"></span><span class="wait" style="width:${w(l.waitMinutes)}"></span><span class="offunit" style="width:${w(l.offUnitMinutes)}"></span><span class="unbooked" style="width:${w(unbooked)}"></span></div>`;}
function operationsPanel(known){const ops=state.operations,h=ops.requiredMinutes/60;
 return `<div class="operations-row"><section class="insight-card operations-panel"><div class="section-top"><h2>Standard day</h2><span class="hypothesis-badge">SET BY OPERATIONS</span></div><form id="operations-form" class="operations-form"><label class="field">Hours per day<input name="requiredHours" type="number" min="1" max="24" step="0.25" required value="${h}"></label><button class="button">Save</button><p class="form-hint">${ops.workDays} days × ${fmtBand(h)} h = ${fmtBand(h*ops.workDays)} h a week. Additional hours are entered by the lead on the job, and the person's day and goal grow to match. There is no approval step.</p></form></section><section class="insight-card operations-panel"><div class="section-top"><h2>Training center and off-unit time</h2><span class="hypothesis-badge">ENTERED BY THE LEAD</span></div><form id="offunit-form" class="operations-form"><label class="field">Person<input name="person" list="operator-names" required maxlength="80" autocomplete="off"></label><label class="field">Hours on ${shortDate(selectedDate)}<input name="hours" type="number" min="0.25" max="24" step="0.25" required></label><label class="field">For<select name="reason">${QuestTracking.OFF_UNIT_REASONS.map(r=>`<option>${esc(r)}</option>`).join('')}</select></label><button class="button">Add</button><datalist id="operator-names">${known.map(n=>`<option value="${esc(n)}">`).join('')}</datalist><p class="form-error" id="offunit-error" role="alert"></p><p class="form-hint">Training isn't in the manpower plan, so add it when it happens, including a trainer's time on the floor. It counts toward the person's day, not toward any unit or goal.</p></form></section></div>`;}
function renderOperators(){
 const people=new Map(),add=name=>people.has(QuestTracking.key(name))||people.set(QuestTracking.key(name),name);
 activeJobs().filter(j=>j.date===selectedDate).forEach(j=>QuestTracking.names(j.operators).forEach(add));state.offUnit.filter(o=>o.date===selectedDate).forEach(o=>add(o.name));
 const known=[...new Set(activeJobs().flatMap(j=>QuestTracking.names(j.operators)))].sort();
 $('#page-content').innerHTML=`${operationsPanel(known)}<div class="section-top"><h2>Operator day · ${shortDate(selectedDate)} · all shifts and cells</h2></div><p class="form-hint">Did each person's day get booked? The day is the standard ${fmtHours(state.operations.requiredMinutes/60)} h plus any additional hours the lead entered. Waiting counts toward the day but not toward building, so it never counts against the person. Standard hours describe the unit's progress; shared values are team context, not individual credit.</p><div class="hours-legend"><span><i class="work"></i>Building</span><span><i class="wait"></i>Waiting</span><span><i class="offunit"></i>Training / off-unit</span><span><i class="unbooked"></i>Not booked</span></div>${[...people.values()].sort().map(name=>{const l=QuestTracking.ledger(activeJobs(),{name,date:selectedDate,operations:state.operations,offUnit:state.offUnit}),off=state.offUnit.filter(o=>o.date===selectedDate&&QuestTracking.key(o.name)===QuestTracking.key(name));
  return `<section class="operator-day insight-card"><div class="section-top"><h2>${esc(name)}</h2><span class="secondary-text">${fmtHours(l.requiredMinutes/60)} h day${l.overtimeMinutes?` · ${fmtHours(l.overtimeMinutes/60)} h additional`:''}</span></div>${hoursMeter(l)}<p>${fmtHours(l.buildMinutes/60)} h building · ${fmtHours(l.waitMinutes/60)} h waiting${l.offUnitMinutes?` · ${fmtHours(l.offUnitMinutes/60)} h training / off-unit`:''} · ${fmtHours(Math.max(0,l.requiredMinutes-l.bookedMinutes)/60)} h not booked${l.overMinutes?` · <b>${fmtHours(l.overMinutes/60)} h over the day</b>`:''}</p>${l.rows.map(r=>{const j=activeJobs().find(x=>x.id===r.id),others=QuestTracking.names(j.operators).filter(n=>QuestTracking.key(n)!==QuestTracking.key(name));return `<div class="operator-unit"><div><strong>${esc(j.job)} · ${esc(j.cell)} · Shift ${esc(j.shift)}</strong><p>${contribution(j)}</p><p>${observedTime(j)}${others.length?' · shared with '+esc(others.join(', ')):''}</p><p class="grades-line">${gradesText(j)}</p><p>${esc(j.comment)}</p></div><div><button class="button" data-trace="${esc(j.id)}">Unit history</button><button class="button" data-edit="${esc(j.id)}">Edit</button><button class="button" data-next-unit="${esc(j.id)}">Next unit this shift</button></div></div>`;}).join('')}${off.map(o=>`<div class="operator-unit offunit-row"><div><strong>${esc(o.reason)} · ${fmtHours(o.minutes/60)} h</strong><p>Not on a unit · entered by the lead</p></div><div><button class="button" data-remove-offunit="${esc(o.id)}">Remove</button></div></div>`).join('')}</section>`;}).join('')||'<p>No assignments on this day.</p>'}`;
}
function saveOperations(e){
 e.preventDefault();const f=e.target;
 if(f.id==='operations-form'){const minutes=Math.round(Number(f.elements.requiredHours.value)*60);if(!Number.isFinite(minutes)||minutes<60||minutes>1440){notify('Enter a standard day between 1 and 24 hours.');return;}state.operations={...state.operations,requiredMinutes:minutes};notify(`Standard day set to ${fmtHours(minutes/60)} h`);}
 else{const entry={id:newId(),date:selectedDate,name:f.elements.person.value.trim().replace(/\s+/g,' '),minutes:Math.round(Number(f.elements.hours.value)*60),reason:f.elements.reason.value},error=QuestTracking.validateOffUnit(entry,activeJobs(),state.operations,state.offUnit);if(error){$('#offunit-error').textContent=error;return;}state.offUnit=[...state.offUnit,entry];notify(`${entry.name} · ${fmtHours(entry.minutes/60)} h ${entry.reason.toLowerCase()} added`);}
 saveState();render();
}
// Insights: the worker view and the unit view answer different questions, so they are never combined into one score.
function flowInsights(jobs){
 const dates=view==='week'?weekDates():[selectedDate],end=dates.at(-1),keys=new Set(jobs.map(QuestProduction.unitKey)),hoursOpts={dates,operations:state.operations,offUnit:state.offUnit,earned:earnedMinutes};
 const units=QuestTracking.unitFlow(activeJobs().filter(j=>keys.has(QuestProduction.unitKey(j))&&j.date<=end).sort(QuestProduction.compare),earnedMinutes).sort((a,b)=>b.lostMinutes-a.lostMinutes||b.waitMinutes-a.waitMinutes);
 const overtimeOnly=peopleView==='overtime',people=overtimeOnly?QuestTracking.personDays(activeJobs(),hoursOpts).filter(d=>d.overtimeMinutes>0).sort((a,b)=>b.date.localeCompare(a.date)||a.name.localeCompare(b.name)):QuestTracking.workers(activeJobs(),hoursOpts).sort((a,b)=>b.unbookedMinutes-a.unbookedMinutes||b.overMinutes-a.overMinutes||a.name.localeCompare(b.name));
 const delays=QuestTracking.delaySummary(jobs),vital=delays.rows.filter(r=>r.vital),max=delays.rows[0]?.minutes||1;
 const pareto=delays.rows.length?`<p class="pareto-lead"><strong>${vital.map(r=>esc(r.reason)).join(' + ')}</strong> account${vital.length===1?'s':''} for ${Math.round(vital.at(-1).cumulative)}% of the ${fmtHours(delays.total/60)} h of recorded waiting.</p><div class="pareto">${delays.rows.map(r=>`<details class="pareto-row ${r.vital?'vital':''}"><summary><span class="pareto-label">${esc(r.reason)}</span><span class="pareto-track"><i style="width:${r.minutes/max*100}%"></i></span><span class="pareto-value">${fmtHours(r.minutes/60)} h<small>${Math.round(r.share)}% · cum. ${Math.round(r.cumulative)}%</small></span></summary><div class="pareto-jobs">${r.jobs.map(j=>`<button class="text-button" data-trace="${esc(j.id)}">${esc(j.job)} · ${esc(j.cell)} · ${shortDate(j.date)} · Shift ${esc(j.shift)} · ${fmtHours(j.delayMinutes/60)} h</button>`).join('')}</div></details>`).join('')}</div>`:'<p class="form-hint">No waiting time recorded in this view.</p>';
 return `<section class="insight-card flow-card wide"><div class="section-top"><h2>Why units wait · 80/20</h2><span class="secondary-text">${delays.known} assignment${delays.known===1?'':'s'} with waiting recorded</span></div>${pareto}<p class="form-hint">Waiting hours by reason, largest first. The highlighted reasons together reach 80% of the total, so they are the place to start. Open a reason to see the units.</p></section>
 <section class="insight-card flow-card wide"><div class="section-top"><h2>Units · where the time went</h2><span class="secondary-text">Whole unit to ${shortDate(end)}</span></div><div class="table-scroll"><table class="supervisor-table flow-table"><thead><tr><th>Unit</th><th>Time study earned</th><th>Hours to build</th><th>vs. time study</th><th>Waiting</th><th>Process</th><th>Main reason</th></tr></thead><tbody>${units.map(u=>`<tr class="${u.lostMinutes>=0.15*u.standardMinutes&&u.lostMinutes>0?'flagged':''}"><td><button class="text-button" data-trace="${esc(u.latest.id)}">${esc(u.latest.job)}</button><small>${esc(u.latest.cell)} · ${u.assignments} assignment${u.assignments===1?'':'s'}</small></td><td>${fmtHours(u.standardMinutes/60)} h</td><td>${fmtHours(u.buildMinutes/60)} h</td><td>${signedHours(u.overMinutes)}</td><td>${u.waitMinutes?fmtHours(u.waitMinutes/60)+' h':'—'}</td><td>${pct(u.processEfficiency)}</td><td>${esc(u.reasons[0]?.[0]||'—')}</td></tr>`).join('')||'<tr><td colspan="7">No units in this view.</td></tr>'}</tbody></table></div><p class="form-hint">Unit questions: did this unit take longer than the time study, and why? Hours to build are the hours worked on the unit minus waiting; each assignment counts once, however many names are on it. Process = 1 − waiting ÷ hours worked. Rows where the overage plus waiting reaches 15% of the time study are highlighted.</p></section>
 <section class="insight-card flow-card wide"><div class="section-top"><h2>People · did the day add up</h2><label class="people-filter">Show <select id="people-view"><option value="all" ${overtimeOnly?'':'selected'}>Everyone</option><option value="overtime" ${overtimeOnly?'selected':''}>Worked additional hours (more than ${fmtHours(state.operations.requiredMinutes/60)} h)</option></select></label></div><div class="table-scroll"><table class="supervisor-table flow-table"><thead><tr><th>${overtimeOnly?'Person · day':'Person'}</th><th>Day</th><th>Additional</th><th>Building</th><th>Waiting</th><th>Training / off-unit</th><th>Not booked</th><th>Standard h earned · grade</th></tr></thead><tbody>${people.map(p=>{const vs=p.earnedMinutes-p.buildMinutes;return `<tr class="${overtimeOnly?(vs<=-90?'flagged':''):(p.overMinutes||p.unbookedMinutes>=0.1*p.dayMinutes?'flagged':'')}"><td><strong>${esc(p.name)}</strong><small>${overtimeOnly?shortDate(p.date,{weekday:'short',month:'short',day:'numeric'})+' · ':''}${p.units} unit${p.units===1?'':'s'}</small></td><td>${fmtHours(p.dayMinutes/60)} h</td><td>${p.overtimeMinutes?fmtHours(p.overtimeMinutes/60)+' h':'—'}</td><td>${fmtHours(p.buildMinutes/60)} h</td><td>${p.waitMinutes?fmtHours(p.waitMinutes/60)+' h':'—'}</td><td>${p.offUnitMinutes?fmtHours(p.offUnitMinutes/60)+' h':'—'}</td><td>${p.overMinutes?`${fmtHours(p.overMinutes/60)} h over`:fmtHours(p.unbookedMinutes/60)+' h'}</td><td>${fmtHours(p.earnedMinutes/60)} h<small>Person grade ${pct(p.personGrade)}${overtimeOnly?` · ${signedHours(vs)} vs. hours building`:''}</small></td></tr>`;}).join('')||`<tr><td colspan="8">${overtimeOnly?'No additional hours in this range.':'No assignments in this range.'}</td></tr>`}</tbody></table></div><p class="form-hint">${overtimeOnly?'Each row is one person\'s day with additional hours, to check against time cards: the standard day plus the additional hours the lead entered, the hours spent building once waiting is taken off, and the standard hours earned on that person\'s assignments. Waiting is not held against the person: person grade = standard hours earned ÷ hours building. Highlighted: standard hours earned 1.5 h or more below the hours building. Shared assignments count fully for each person on them, so read those as team output.':'Was the day (standard hours plus additional hours) booked to units or training, across every cell and shift? A person can book a full day while their units still lose time; that is a unit problem, not a person problem. Highlighted: 10% or more of the day not booked, or time over the day.'} ${dates.length===1?shortDate(end):'Selected week'} · all processes and cells.</p></section>`;
}
// Station alerts: what the supervisor scans for. They follow the process (blocked, at risk, or efficiency lost to waiting), not the person.
const DEFAULT_ALERTS={warnBelow:0.9,criticalBelow:0.75,repeatAt:2};
const processOf=j=>QuestTracking.grades(j).process;
function stationAlerts(date=selectedDate){return QuestProduction.stationAlerts(state.jobs,{date,efficiency:processOf,...state.alertSettings,acknowledged:state.alertAcks});}
const alertLabel=a=>a.reasons.includes('blocked')?'Blocked':a.reasons.includes('process')?`Process ${pct(a.processEfficiency)}`:'At risk';
function alertReasons(a){const j=a.job,h=QuestTracking.hours(j),lines=[];
 if(a.reasons.includes('blocked'))lines.push(`Reported blocked${j.closed?'':' · shift in progress'}`);
 if(a.reasons.includes('at-risk'))lines.push('Reported at risk · shift in progress');
 if(a.reasons.includes('process'))lines.push(`Process efficiency ${pct(a.processEfficiency)}: ${fmtHours(h.waitMinutes/60)} h waiting of ${fmtHours(h.workedMinutes/60)} h${j.delayReason?' · '+j.delayReason:''}`);
 if(a.streak>=2)lines.push(`Behind ${a.streak} assignments in a row at this station`);
 if(j.closed&&!j.training){const g=QuestTracking.grades(j,earnedMinutes(j)).person;if(g!=null)lines.push(`Person grade ${pct(g)}${ratingOf(j)?' · '+statusNames['rating-'+ratingOf(j)]:''}: the operator's own work, shown for context`);}
 return lines;}
const alertChip=a=>a?`<span class="alert-chip ${a.level}${a.acknowledged?' acknowledged':''}">${icon('alert')}${alertLabel(a)}</span>`:'';
// One badge per cell: its most urgent alert (the list is already ordered by urgency).
const alertsByCell=date=>stationAlerts(date).reduce((map,a)=>map.has(a.cell)?map:map.set(a.cell,a),new Map());
function alertNotice(j){const a=stationAlerts(j.date).find(a=>a.job.id===j.id&&!a.acknowledged);return a?`${a.cell} · ${alertReasons(a)[0]}`:'';}
function updateAlertBell(){const n=stationAlerts().filter(a=>!a.acknowledged).length;$('#alert-count').textContent=n||'';$('#alert-bell').classList.toggle('has-alerts',n>0);$('#alert-bell').setAttribute('aria-label',`Station alerts: ${n} active on ${shortDate(selectedDate)}`);}
function alertStrip(){const active=[...alertsByCell(selectedDate).values()].filter(a=>!a.acknowledged);return active.length?`<div class="alert-strip" role="status">${icon('alert')}<strong>${active.length} station${active.length===1?'':'s'} need${active.length===1?'s':''} attention</strong>${active.map(a=>`<span class="${a.level}">${esc(a.cell)} · ${alertLabel(a)}</span>`).join('')}</div>`:'';}
function renderAlerts(){
 const alerts=stationAlerts(),active=alerts.filter(a=>!a.acknowledged),done=alerts.filter(a=>a.acknowledged),rules=state.alertSettings;
 const row=a=>{const j=a.job,s=stepInfo(j),ack=state.alertAcks[a.key];return `<article class="alert-row ${a.level}${a.acknowledged?' acknowledged':''}"><div class="alert-level">${icon('alert')}<span>${a.level==='critical'?'Critical':'Warning'}</span></div><div class="alert-body"><h3>${esc(j.cell)} · ${esc(j.job)} · ${alertLabel(a)}</h3><p class="alert-meta">Shift ${esc(j.shift)} · ${esc(j.operators)} · ${esc(j.part)} · Stop ${esc(stepText(s.stop))} · Goal ${esc(stepText(s.goal))}</p><ul>${alertReasons(a).map(r=>`<li>${esc(r)}</li>`).join('')}</ul>${j.comment?`<p class="alert-comment">“${esc(j.comment)}”</p>`:''}${ack?`<p class="alert-meta">Acknowledged at ${new Date(ack.at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</p>`:''}</div><div class="alert-actions"><button class="button" data-trace="${esc(j.id)}">Unit history</button><button class="button" data-edit="${esc(j.id)}">Update job</button>${a.acknowledged?`<button class="button" data-unack="${esc(a.key)}">Reopen</button>`:`<button class="button primary" data-ack="${esc(a.key)}">Acknowledge</button>`}</div></article>`;};
 $('#page-content').innerHTML=`<div class="section-top"><h2>Stations needing attention · ${shortDate(selectedDate,{weekday:'long',month:'long',day:'numeric'})} <span class="count-pill">${active.length} active</span></h2></div><div class="alert-list">${active.map(row).join('')||'<div class="empty-state"><h3>No stations behind.</h3><p>No station is blocked, at risk, or losing process time to waiting on this day.</p></div>'}</div>${done.length?`<div class="section-top alert-subhead"><h2>Acknowledged <span class="count-pill">${done.length}</span></h2></div><div class="alert-list">${done.map(row).join('')}</div>`:''}<section class="insight-card alert-settings"><h2>Alert rules</h2><form id="alert-form" class="operations-form"><label class="field">Warning: process efficiency below (%)<input name="warnBelow" type="number" min="1" max="100" step="1" required value="${Math.round(rules.warnBelow*100)}"></label><label class="field">Critical: process efficiency below (%)<input name="criticalBelow" type="number" min="1" max="100" step="1" required value="${Math.round(rules.criticalBelow*100)}"></label><label class="field">Critical after this many behind in a row<input name="repeatAt" type="number" min="2" max="10" step="1" required value="${rules.repeatAt}"></label><button class="button">Save rules</button></form><p class="form-hint">Process efficiency = 1 − waiting ÷ total hours (regular + additional). 3 h waiting in an 11 h day is 73%. Each station uses its latest assignment on this day. Blocked is always critical; At risk alerts while the shift is running. Whether the operator met the goal is a person question: see the person grade on Supervisor review, Operator day, and Insights. Acknowledging hides an alert from the bell and TV until that assignment changes.</p></section>`;
}
function saveAlertRules(e){e.preventDefault();const f=e.target,warnBelow=Number(f.elements.warnBelow.value)/100,criticalBelow=Number(f.elements.criticalBelow.value)/100,repeatAt=Number(f.elements.repeatAt.value);if(![warnBelow,criticalBelow].every(n=>Number.isFinite(n)&&n>0&&n<=1)||criticalBelow>warnBelow||!Number.isInteger(repeatAt)||repeatAt<2){notify('Critical must be at or below the warning line (1–100%), and the repeat count 2 or more.');return;}state.alertSettings={warnBelow,criticalBelow,repeatAt};saveState();render();notify('Alert rules saved');}
function openRemoval(id){const j=activeJobs().find(j=>j.id===id);if(!j||tv)return;$('#remove-form').reset();$('#remove-id').value=id;$('#remove-label').textContent=`Remove ${j.job} from the active board?`;$('#remove-dialog').showModal();}
function removeJob(e){e.preventDefault();const j=activeJobs().find(j=>j.id===$('#remove-id').value);if(!j)return;const unit=$('#remove-scope').value==='unit',rows=unit?activeJobs().filter(r=>QuestProduction.unitKey(r)===QuestProduction.unitKey(j)):[j];const at=new Date().toISOString(),batch=newId();state.jobs=QuestProduction.changeRemoved(state.jobs,rows.map(r=>r.id),at,batch);for(const row of rows)state.history.unshift(QuestStorage.historySnapshot(row,null,unit?'Unit removed':'Assignment removed',at,newId(),{...snapshotDetail(row),removalReason:$('#remove-reason').value,comment:`Removed: ${$('#remove-reason').value||'Entry correction'}`}));saveState();$('#remove-dialog').close();render();notify('Removed from board · recover it in Removed jobs');}
function restoreRemoved(batch){const rows=state.jobs.filter(j=>j.deletedAt&&j.deleteBatch===batch);if(rows.some(j=>validateContinuity(j)||activeJobs().some(r=>r.processId===j.processId&&r.job.toLowerCase()===j.job.toLowerCase()&&r.date===j.date&&r.shift===j.shift))){notify('Restore blocked: an active record conflicts with this unit’s identity, shift or progress. Correct it first.');return;}state.jobs=QuestProduction.changeRemoved(state.jobs,rows.map(j=>j.id),null,null);rows.forEach(j=>state.history.unshift(QuestStorage.historySnapshot(j,null,'Restored',new Date().toISOString(),newId(),snapshotDetail(j))));saveState();render();notify('Records restored');}
function renderRemoved(){const groups=new Map();state.jobs.filter(j=>j.deletedAt).forEach(j=>groups.set(j.deleteBatch,[...(groups.get(j.deleteBatch)||[]),j]));$('#page-content').innerHTML=`<h2>Removed jobs</h2><p>Removed records are excluded from current boards and operator totals. History remains available.</p><div class="trace-list">${[...groups].map(([batch,rows])=>`<article><h3>${esc(rows[0].job)} · ${rows.length} assignment(s)</h3><p>${rows.map(j=>`${shortDate(j.date)} · Shift ${esc(j.shift)} · ${esc(j.operators)}`).join('<br>')}</p><button class="button" data-restore="${esc(batch)}">Restore</button></article>`).join('')||'<p>No removed jobs.</p>'}</div>`;}
function tvControls(){return `<div class="tv-controls"><label>Display <select id="tv-layout"><option value="cells" ${tvLayout==='cells'?'selected':''}>Unit / cell grid</option><option value="goals" ${tvLayout==='goals'?'selected':''}>Operator goals</option></select></label><button class="button" id="tv-pause">${tvPaused?'Resume rotation':'Pause rotation'}</button><button class="button" id="next-tv-page">Next page</button><button class="button" id="tv-fullscreen">Full screen</button></div>`;}
function renderTvCells(){const alerts=alertsByCell(selectedDate),units=floorUnits(selectedDate),entries=CELL_NAMES.flatMap(cell=>{const rows=units.filter(j=>j.cell===cell);return rows.length?rows.map(j=>({cell,j})):[{cell}];}),size=window.innerWidth<700?3:window.innerHeight<900?6:12,pages=Math.ceil(entries.length/size);tvPage%=pages;$('#page-content').innerHTML=tvControls()+alertStrip()+`<div class="section-top"><h2>${shortDate(selectedDate)} · All shifts · unit progress</h2><span>Page ${tvPage+1} / ${pages} · ${tvPaused?'Paused':'20 seconds'}</span></div><div class="tv-cell-grid">${entries.slice(tvPage*size,tvPage*size+size).map(({cell,j})=>`<article class="tv-unit ${j?'shade-'+(percent(j)===100?4:Math.min(3,Math.floor(percent(j)/25))):'empty-cell'} ${alerts.get(cell)&&!alerts.get(cell).acknowledged?'alert-'+alerts.get(cell).level:''}"><h3>${cell}${j?' · '+esc(j.job):''}${alerts.get(cell)?.acknowledged?'':alertChip(alerts.get(cell))}</h3><strong>${j?percent(j)+'%':'—'}</strong><p>${j?esc(j.end?'Stop '+j.end+' · '+namesOf(j)[j.end-1]:'No step completed'):'No record'}</p><small>${j?shortDate(j.date)+' · Shift '+esc(j.shift):'No assembly recorded'}</small></article>`).join('')}</div>`;}
function validateContinuity(j){
 const unit=activeJobs().filter(r=>r.id!==j.id&&r.unitId===j.unitId);
 if(activeJobs().some(r=>r.unitId!==j.unitId&&r.processId===j.processId&&r.job.toLowerCase()===j.job.toLowerCase()))return 'That job number belongs to another unit. Choose a unique number.';
 const prior=unit.filter(r=>QuestProduction.compare({...r,updatedAt:''},{...j,updatedAt:''})<0).sort(QuestProduction.compare).at(-1);
 const next=unit.filter(r=>QuestProduction.compare({...r,updatedAt:''},{...j,updatedAt:''})>0).sort(QuestProduction.compare)[0];
 if(prior&&j.start<prior.end)return 'Start overlaps the prior assignment. Review the unit history and correct the earlier stop first.';
 if(next&&j.end>next.start)return 'Stop overlaps a later assignment. Review that assignment before changing this stop.';
 return '';
}
function recordCorrection(previous,updated){
 // Preserve both sides of a correction; a renamed unit keeps its stable identity.
 const remember=(row,kind)=>state.history.unshift(QuestStorage.historySnapshot(row,null,kind,updated.updatedAt,newId(),snapshotDetail(row)));
 remember(previous,'Before correction');
 state.jobs=state.jobs.map(row=>{if(row.id===updated.id)return updated;if(row.unitId===previous.unitId&&row.job!==updated.job){remember(row,'Before job number correction');const renamed={...row,job:updated.job};remember(renamed,'Job number corrected');return renamed;}return row;});
}
function initWorkflow(){
 $('#remove-form').addEventListener('submit',removeJob);$('#cancel-remove').onclick=()=>$('#remove-dialog').close();
 // Capture runs before the form's own input handler, so a typed plan is never overwritten.
 document.addEventListener('input',e=>{if(e.target.name==='allocationHours')autoPlan=false;},true);
 document.addEventListener('submit',e=>{if(['operations-form','offunit-form'].includes(e.target.id))saveOperations(e);if(e.target.id==='alert-form')saveAlertRules(e);});
 document.addEventListener('click',e=>{
  const remove=e.target.closest('[data-remove]');if(remove)openRemoval(remove.dataset.remove);
  const restore=e.target.closest('[data-restore]');if(restore)restoreRemoved(restore.dataset.restore);
  const next=e.target.closest('[data-next-unit]');if(next)nextUnit(next.dataset.nextUnit);
  const ack=e.target.closest('[data-ack]');if(ack){state.alertAcks={...state.alertAcks,[ack.dataset.ack]:{at:new Date().toISOString()}};saveState();render();notify('Acknowledged · it returns if that assignment changes');}
  const unack=e.target.closest('[data-unack]');if(unack){const alertAcks={...state.alertAcks};delete alertAcks[unack.dataset.unack];state.alertAcks=alertAcks;saveState();render();}
  const offunit=e.target.closest('[data-remove-offunit]');if(offunit){state.offUnit=state.offUnit.filter(o=>o.id!==offunit.dataset.removeOffunit);saveState();render();notify('Off-unit time removed');}
  if(e.target.closest('#tv-pause')){tvPaused=!tvPaused;render();}
  if(e.target.closest('#tv-fullscreen')){const promise=document.fullscreenElement?document.exitFullscreen?.():document.documentElement.requestFullscreen?.();promise?.catch(()=>notify('Use your browser’s full-screen option on this device.'));}
 });
 document.addEventListener('change',e=>{if(e.target.id==='tv-layout'){tvLayout=e.target.value;tvPage=0;render();}if(e.target.id==='people-view'){peopleView=e.target.value;render();}});
 window.addEventListener('resize',()=>{if(tv)render();});
}
